/**
 * =========================================================
 * RuntimeSocketManager
 * =========================================================
 *
 * Canonical websocket projection layer.
 *
 * IMPORTANT
 * ---------------------------------------------------------
 * Frontend transport is NOT runtime authority.
 *
 * Runtime authority belongs to:
 *
 *   - backend runtime
 *   - replay engine
 *   - receipt lineage
 *   - runtime event schema
 *
 * This layer only:
 *
 *   - ingests
 *   - normalizes
 *   - caches
 *   - dispatches
 *   - visualizes
 *
 * NEVER derive runtime truth here.
 */

import {
    unwrapRuntimePacketEnvelope,
    validateRuntimeContract
} from "./RuntimeContractEnvelope"

export type RuntimeEventType =

    | "runtime"
    | "replay"
    | "graph"
    | "transport"
    | "receipt"
    | "certification"

// =========================================================
// Config
// =========================================================

export interface RuntimeSocketConfig {

    runtimeEndpoint: string

    replayEndpoint: string

    graphEndpoint: string

    transportEndpoint: string

    reconnectDelayMs?: number
}

// =========================================================
// Event
// =========================================================

export interface RuntimeSocketEvent {

    event_type: RuntimeEventType

    channel?: string

    source_event_type?: string

    kernel_tick?: number

    runtime_state_hash72?: string

    conformance_root?: string

    zero_bypass_status?: string

    gui_projection_valid?: boolean

    gui_projection_reasons?: string[]

    timestamp_ns: number

    sequence_id?: number

    authority?: string

    runtime_id?: string

    branch_id?: string

    event_hash72?: string

    parent_event_hash72?: string

    receipt_hash72?: string

    contract_hash72?: string

    payload_hash72?: string

    contract_valid?: boolean

    contract_reasons?: string[]

    payload: Record<
        string,
        unknown
    >
}

// =========================================================
// Channel Health
// =========================================================

export interface RuntimeChannelHealth {

    channel: RuntimeEventType

    endpoint: string

    connected: boolean

    status: "LIVE_KERNEL_CONNECTED" | "NO_LIVE_KERNEL_SOURCE" | "STALE_LIVE_KERNEL_STATE"

    lastSequenceId?: number

    lastKernelTick?: number

    lastReceiptHash72?: string

    lastRuntimeStateHash72?: string

    lastEventHash72?: string

    lastPacketAgeMs?: number

    totalEvents: number
}

// =========================================================
// State
// =========================================================

export interface RuntimeSocketState {

    runtimeConnected: boolean

    replayConnected: boolean

    graphConnected: boolean

    transportConnected: boolean

    runtimeHistory:
        RuntimeSocketEvent[]

    replayHistory:
        RuntimeSocketEvent[]

    graphHistory:
        RuntimeSocketEvent[]

    transportHistory:
        RuntimeSocketEvent[]

    lastRuntimeEvent?:
        RuntimeSocketEvent

    lastReplayEvent?:
        RuntimeSocketEvent

    lastGraphEvent?:
        RuntimeSocketEvent

    lastTransportEvent?:
        RuntimeSocketEvent

    totalEvents: number
}

// =========================================================
// Listener
// =========================================================

export type RuntimeSocketListener = (

    event: RuntimeSocketEvent

) => void

// =========================================================
// RuntimeSocketManager
// =========================================================

export class RuntimeSocketManager {

    public readonly config:
        RuntimeSocketConfig

    public readonly state:
        RuntimeSocketState

    private runtimeSocket?:
        WebSocket

    private replaySocket?:
        WebSocket

    private graphSocket?:
        WebSocket

    private transportSocket?:
        WebSocket

    private readonly listeners =
        new Map<
            RuntimeEventType,
            Set<RuntimeSocketListener>
        >()

    private readonly reconnectDelayMs:
        number

    private shutdownRequested =
        false

    private readonly maxHistory =
        2048

    // =====================================================
    // Constructor
    // =====================================================

    constructor(
        config: RuntimeSocketConfig
    ) {

        this.config = config

        this.reconnectDelayMs = (

            config.reconnectDelayMs
            ??
            3000
        )

        this.state = {

            runtimeConnected: false,

            replayConnected: false,

            graphConnected: false,

            transportConnected: false,

            runtimeHistory: [],

            replayHistory: [],

            graphHistory: [],

            transportHistory: [],

            totalEvents: 0
        }
    }

    // =====================================================
    // Initialize
    // =====================================================

    public async initialize():
        Promise<void> {

        this.shutdownRequested =
            false

        this.connectRuntime()

        this.connectReplay()

        this.connectGraph()

        this.connectTransport()
    }

    // =====================================================
    // Runtime
    // =====================================================

    private connectRuntime():
        void {

        this.runtimeSocket =
            new WebSocket(

                this.toSocketURL(

                    this.config
                        .runtimeEndpoint
                )
            )

        this.runtimeSocket.onopen =
            () => {

            this.state
                .runtimeConnected = true

            console.log(
                "[runtime/ws] connected"
            )
        }

        this.runtimeSocket.onclose =
            () => {

            this.state
                .runtimeConnected = false

            console.log(
                "[runtime/ws] disconnected"
            )

            this.scheduleReconnect(
                "runtime"
            )
        }

        this.runtimeSocket.onerror =
            (error) => {

            console.error(

                "[runtime/ws] error",

                error
            )
        }

        this.runtimeSocket.onmessage =
            (message) => {

            this.handleEvent(

                "runtime",

                message.data
            )
        }
    }

    // =====================================================
    // Replay
    // =====================================================

    private connectReplay():
        void {

        this.replaySocket =
            new WebSocket(

                this.toSocketURL(

                    this.config
                        .replayEndpoint
                )
            )

        this.replaySocket.onopen =
            () => {

            this.state
                .replayConnected = true

            console.log(
                "[replay/ws] connected"
            )
        }

        this.replaySocket.onclose =
            () => {

            this.state
                .replayConnected = false

            console.log(
                "[replay/ws] disconnected"
            )

            this.scheduleReconnect(
                "replay"
            )
        }

        this.replaySocket.onerror =
            (error) => {

            console.error(

                "[replay/ws] error",

                error
            )
        }

        this.replaySocket.onmessage =
            (message) => {

            this.handleEvent(

                "replay",

                message.data
            )
        }
    }

    // =====================================================
    // Graph
    // =====================================================

    private connectGraph():
        void {

        this.graphSocket =
            new WebSocket(

                this.toSocketURL(

                    this.config
                        .graphEndpoint
                )
            )

        this.graphSocket.onopen =
            () => {

            this.state
                .graphConnected = true

            console.log(
                "[graph/ws] connected"
            )
        }

        this.graphSocket.onclose =
            () => {

            this.state
                .graphConnected = false

            console.log(
                "[graph/ws] disconnected"
            )

            this.scheduleReconnect(
                "graph"
            )
        }

        this.graphSocket.onerror =
            (error) => {

            console.error(

                "[graph/ws] error",

                error
            )
        }

        this.graphSocket.onmessage =
            (message) => {

            this.handleEvent(

                "graph",

                message.data
            )
        }
    }

    // =====================================================
    // Transport
    // =====================================================

    private connectTransport():
        void {

        this.transportSocket =
            new WebSocket(

                this.toSocketURL(

                    this.config
                        .transportEndpoint
                )
            )

        this.transportSocket.onopen =
            () => {

            this.state
                .transportConnected = true

            console.log(
                "[transport/ws] connected"
            )
        }

        this.transportSocket.onclose =
            () => {

            this.state
                .transportConnected = false

            console.log(
                "[transport/ws] disconnected"
            )

            this.scheduleReconnect(
                "transport"
            )
        }

        this.transportSocket.onerror =
            (error) => {

            console.error(

                "[transport/ws] error",

                error
            )
        }

        this.transportSocket.onmessage =
            (message) => {

            this.handleEvent(

                "transport",

                message.data
            )
        }
    }

    // =====================================================
    // Handle Event
    // =====================================================

    private handleEvent(

        channel:
            RuntimeEventType,

        raw:
            string

    ): void {

        try {

            const parsed =

                this.normalizeEvent(

                    channel,

                    JSON.parse(raw)
                )

            this.appendHistory(

                channel,

                parsed
            )

            this.dispatchEvent(
                parsed
            )

            this.state.totalEvents += 1

            switch (channel) {

                case "runtime":

                    this.state
                        .lastRuntimeEvent =
                            parsed

                    break

                case "replay":

                    this.state
                        .lastReplayEvent =
                            parsed

                    break

                case "graph":

                    this.state
                        .lastGraphEvent =
                            parsed

                    break

                case "transport":

                    this.state
                        .lastTransportEvent =
                            parsed

                    break
            }

        } catch (error) {

            console.error(

                "[RuntimeSocketManager] parse failure",

                error
            )
        }
    }

    // =====================================================
    // Normalize
    // =====================================================

    private normalizeEvent(

        channel:
            RuntimeEventType,

        raw:
            Record<string, unknown>

    ): RuntimeSocketEvent {

        const packetEnvelope =
            unwrapRuntimePacketEnvelope(raw)

        const apiValidation =
            raw.runtime_contract

                ? validateRuntimeContract(
                    raw.runtime_contract,
                    "api_response"
                )

                : { ok: false, reasons: ["api response contract missing"] }

        const payload =

            packetEnvelope.runtime_packet

                ? packetEnvelope.payload

                : (
                    typeof raw.payload === "object"
                    &&
                    raw.payload !== null

                        ? raw.payload as Record<
                            string,
                            unknown
                        >

                        : {}
                )

        const contractHash72 =
            typeof packetEnvelope.runtime_packet?.contract_hash72 === "string"

                ? packetEnvelope.runtime_packet.contract_hash72

                : (
                    typeof (raw.runtime_contract as Record<string, unknown> | undefined)?.contract_hash72 === "string"

                        ? (raw.runtime_contract as Record<string, unknown>).contract_hash72 as string

                        : undefined
                )

        const payloadHash72 =
            typeof packetEnvelope.runtime_packet?.payload_hash72 === "string"

                ? packetEnvelope.runtime_packet.payload_hash72

                : (
                    typeof (raw.runtime_contract as Record<string, unknown> | undefined)?.payload_hash72 === "string"

                        ? (raw.runtime_contract as Record<string, unknown>).payload_hash72 as string

                        : undefined
                )

        const contractValid =
            packetEnvelope.runtime_packet

                ? packetEnvelope.contract_valid

                : apiValidation.ok

        const contractReasons =
            packetEnvelope.runtime_packet

                ? packetEnvelope.reasons

                : apiValidation.reasons

        return {

            event_type:

                (
                    raw.event_type
                    ??
                    raw.event
                    ??
                    channel
                ) as RuntimeEventType,

            channel:

                typeof raw.channel === "string"
                    ? raw.channel
                    : this.config[`${channel}Endpoint` as keyof RuntimeSocketConfig] as string,

            source_event_type:

                typeof raw.source_event_type === "string"
                    ? raw.source_event_type
                    : undefined,

            kernel_tick:

                typeof raw.kernel_tick === "number"
                    ? raw.kernel_tick
                    : undefined,

            runtime_state_hash72:

                typeof raw.runtime_state_hash72 === "string"
                    ? raw.runtime_state_hash72
                    : undefined,

            conformance_root:

                typeof raw.conformance_root === "string"
                    ? raw.conformance_root
                    : undefined,

            zero_bypass_status:

                typeof raw.zero_bypass_status === "string"
                    ? raw.zero_bypass_status
                    : undefined,

            gui_projection_valid:

                typeof raw.gui_projection_valid === "boolean"
                    ? raw.gui_projection_valid
                    : undefined,

            gui_projection_reasons:

                Array.isArray(raw.gui_projection_reasons)
                    ? raw.gui_projection_reasons.map(String)
                    : undefined,

            timestamp_ns:

                Number(

                    raw.timestamp_ns
                    ??
                    Date.now() * 1_000_000
                ),

            sequence_id:

                typeof raw.sequence_id
                === "number"

                    ? raw.sequence_id

                    : undefined,

            authority:

                typeof raw.authority
                === "string"

                    ? raw.authority

                    : undefined,

            runtime_id:

                typeof raw.runtime_id
                === "string"

                    ? raw.runtime_id

                    : undefined,

            branch_id:

                typeof raw.branch_id
                === "string"

                    ? raw.branch_id

                    : undefined,

            event_hash72:

                typeof raw.event_hash72
                === "string"

                    ? raw.event_hash72

                    : undefined,

            parent_event_hash72:

                typeof raw.parent_event_hash72
                === "string"

                    ? raw.parent_event_hash72

                    : undefined,

            receipt_hash72:

                typeof raw.receipt_hash72
                === "string"

                    ? raw.receipt_hash72

                    : undefined,

            contract_hash72:
                contractHash72,

            payload_hash72:
                payloadHash72,

            contract_valid:
                contractValid,

            contract_reasons:
                contractReasons,

            payload
        }
    }

    // =====================================================
    // History
    // =====================================================

    private appendHistory(

        channel:
            RuntimeEventType,

        event:
            RuntimeSocketEvent

    ): void {

        let target:
            RuntimeSocketEvent[]

        switch (channel) {

            case "runtime":

                target =
                    this.state
                        .runtimeHistory

                break

            case "replay":

                target =
                    this.state
                        .replayHistory

                break

            case "graph":

                target =
                    this.state
                        .graphHistory

                break

            case "transport":

                target =
                    this.state
                        .transportHistory

                break

            default:

                return
        }

        target.push(event)

        if (
            target.length
            >
            this.maxHistory
        ) {

            target.splice(

                0,

                target.length
                -
                this.maxHistory
            )
        }
    }

    // =====================================================
    // Dispatch
    // =====================================================

    private dispatchEvent(
        event: RuntimeSocketEvent
    ): void {

        const listeners =

            this.listeners.get(
                event.event_type
            )

        if (!listeners) {

            return
        }

        for (

            const listener

            of listeners

        ) {

            try {

                listener(event)

            } catch (error) {

                console.error(

                    "[RuntimeSocketManager] listener failure",

                    error
                )
            }
        }
    }

    // =====================================================
    // Subscribe
    // =====================================================

    public subscribe(

        eventType:
            RuntimeEventType,

        listener:
            RuntimeSocketListener

    ): () => void {

        if (

            !this.listeners.has(
                eventType
            )

        ) {

            this.listeners.set(

                eventType,

                new Set()
            )
        }

        this.listeners
            .get(eventType)
            ?.add(listener)

        return () => {

            this.listeners
                .get(eventType)
                ?.delete(listener)
        }
    }

    // =====================================================
    // Reconnect
    // =====================================================

    private scheduleReconnect(
        channel: RuntimeEventType
    ): void {

        if (
            this.shutdownRequested
        ) {

            return
        }

        window.setTimeout(

            () => {

                if (
                    this.shutdownRequested
                ) {

                    return
                }

                switch (channel) {

                    case "runtime":

                        this.connectRuntime()

                        break

                    case "replay":

                        this.connectReplay()

                        break

                    case "graph":

                        this.connectGraph()

                        break

                    case "transport":

                        this.connectTransport()

                        break
                }

            },

            this.reconnectDelayMs
        )
    }

    // =====================================================
    // Channel Health
    // =====================================================

    public getChannelHealth():
        RuntimeChannelHealth[] {

        const now =
            Date.now() * 1_000_000

        const build = (
            channel: RuntimeEventType,
            endpoint: string,
            connected: boolean,
            history: RuntimeSocketEvent[],
            last?: RuntimeSocketEvent
        ): RuntimeChannelHealth => {

            const lastAgeMs =
                last?.timestamp_ns
                    ? Math.max(
                        0,
                        Math.round((now - last.timestamp_ns) / 1_000_000)
                    )
                    : undefined

            const hasKernelSource = Boolean(
                last?.receipt_hash72
                &&
                last?.runtime_state_hash72
                &&
                last?.authority === "HHS_FASTAPI_KERNEL_RUNTIME_AUTHORITY_V1"
            )

            const stale =
                connected
                &&
                typeof lastAgeMs === "number"
                &&
                lastAgeMs > 15000

            return {
                channel,
                endpoint,
                connected,
                status: connected && hasKernelSource
                    ? (stale ? "STALE_LIVE_KERNEL_STATE" : "LIVE_KERNEL_CONNECTED")
                    : "NO_LIVE_KERNEL_SOURCE",
                lastSequenceId: last?.sequence_id,
                lastKernelTick: last?.kernel_tick,
                lastReceiptHash72: last?.receipt_hash72,
                lastRuntimeStateHash72: last?.runtime_state_hash72,
                lastEventHash72: last?.event_hash72,
                lastPacketAgeMs: lastAgeMs,
                totalEvents: history.length
            }
        }

        return [
            build(
                "runtime",
                this.config.runtimeEndpoint,
                this.state.runtimeConnected,
                this.state.runtimeHistory,
                this.state.lastRuntimeEvent
            ),
            build(
                "replay",
                this.config.replayEndpoint,
                this.state.replayConnected,
                this.state.replayHistory,
                this.state.lastReplayEvent
            ),
            build(
                "graph",
                this.config.graphEndpoint,
                this.state.graphConnected,
                this.state.graphHistory,
                this.state.lastGraphEvent
            ),
            build(
                "transport",
                this.config.transportEndpoint,
                this.state.transportConnected,
                this.state.transportHistory,
                this.state.lastTransportEvent
            )
        ]
    }

    // =====================================================
    // Shutdown
    // =====================================================

    public shutdown():
        void {

        this.shutdownRequested =
            true

        this.runtimeSocket?.close()

        this.replaySocket?.close()

        this.graphSocket?.close()

        this.transportSocket?.close()

        this.state.runtimeConnected =
            false

        this.state.replayConnected =
            false

        this.state.graphConnected =
            false

        this.state.transportConnected =
            false
    }

    // =====================================================
    // Metrics
    // =====================================================

    public getMetrics():
        object {

        return {

            runtimeConnected:
                this.state
                    .runtimeConnected,

            replayConnected:
                this.state
                    .replayConnected,

            graphConnected:
                this.state
                    .graphConnected,

            transportConnected:
                this.state
                    .transportConnected,

            runtimeEvents:
                this.state
                    .runtimeHistory
                    .length,

            replayEvents:
                this.state
                    .replayHistory
                    .length,

            graphEvents:
                this.state
                    .graphHistory
                    .length,

            transportEvents:
                this.state
                    .transportHistory
                    .length,

            channelHealth:
                this.getChannelHealth(),

            totalEvents:
                this.state
                    .totalEvents
        }
    }

    // =====================================================
    // Socket URL
    // =====================================================

    private toSocketURL(
        endpoint: string
    ): string {

        const protocol =

            window.location.protocol
                === "https:"

                    ? "wss:"

                    : "ws:"

        if (

            endpoint.startsWith(
                "ws://"
            )

            ||

            endpoint.startsWith(
                "wss://"
            )

        ) {

            return endpoint
        }

        return (

            `${protocol}//`

            +

            `${window.location.host}`

            +

            endpoint
        )
    }
}